:root {
  --card-bg: #ffffff;
  --header-bg: #1a3a2a;
  --accent-green: #2ecc71;
  --accent-light: #a8f0c6;
  --accent-muted: #e8f8ef;
  --text-primary: #1a2e22;
  --text-secondary: #5a7a66;
  --text-inverse: #ffffff;
  --stat-bg: #f2faf6;
  --stat-border: #c8ecd8;
  --bar-color: #2ecc71;
  --bar-bg: #e0f5eb;
  --waypoint-start: #1a3a2a;
  --waypoint-mid: #f39c12;
  --waypoint-end: #27ae60;
  --btn-bg: #2ecc71;
  --btn-text: #0d1f14;
  --footer-border: #dceee4;
}

article.route-card {
  background: var(--card-bg);
  border-radius: 16px;
  width: 460px;
  overflow: hidden;
  border: 1px solid var(--stat-border);
}

.route-header {
  background: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 18px;
}

.route-badge {
  font-size: 28px;
  line-height: 1;
  background: var(--accent-green);
  border-radius: 10px;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.route-meta {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.route-name {
  font-size: 17px;
  font-weight: 700;
  color: var(--text-inverse);
  margin: 0;
  line-height: 1.2;
}

.route-type {
  font-size: 11px;
  color: var(--accent-light);
  font-weight: 500;
  letter-spacing: 0.04em;
}

.route-distance {
  font-size: 22px;
  font-weight: 800;
  color: var(--accent-green);
  letter-spacing: -0.5px;
}

.route-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  border-bottom: 1px solid var(--footer-border);
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 12px 8px;
  background: var(--stat-bg);
  gap: 3px;
  border-right: 1px solid var(--stat-border);
}

.stat:last-child {
  border-right: none;
}

.stat-value {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1;
}

.stat-label {
  font-size: 10px;
  color: var(--text-secondary);
  font-weight: 500;
  text-align: center;
  line-height: 1.2;
}

.elevation-chart {
  padding: 12px 18px 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.chart-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.chart-bars {
  display: flex;
  align-items: flex-end;
  gap: 5px;
  height: 56px;
  background: var(--bar-bg);
  border-radius: 8px;
  padding: 6px 10px;
}

.bar {
  flex: 1;
  height: var(--h);
  background: var(--bar-color);
  border-radius: 3px 3px 0 0;
  opacity: 0.85;
}

.route-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  border-top: 1px solid var(--footer-border);
}

.waypoints {
  display: flex;
  align-items: center;
  gap: 6px;
}

.waypoint {
  font-size: 12px;
  font-weight: 600;
  padding: 4px 9px;
  border-radius: 20px;
}

.waypoint.start {
  background: var(--waypoint-start);
  color: var(--text-inverse);
}

.waypoint.mid {
  background: var(--waypoint-mid);
  color: var(--text-inverse);
}

.waypoint.end {
  background: var(--waypoint-end);
  color: var(--text-inverse);
}

.waypoint-line {
  width: 18px;
  height: 2px;
  background: var(--stat-border);
  border-radius: 1px;
}

.start-btn {
  background: var(--btn-bg);
  color: var(--btn-text);
  border: none;
  border-radius: 20px;
  padding: 9px 20px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  letter-spacing: 0.02em;
}
